INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(43211, 'Exodus 32:33', 'Exodus', 32, 33, 'څښتن موسی ته په ځواب کې وویل: «هرچا چې زما په وړاندې ګناه کړې وي، زه به د هغه نوم د خپل کتاب څخه لېرې کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus32_verse_33.mp3', '', 1761754199, 1761754199),
(43212, 'Exodus 32:34', 'Exodus', 32, 34, 'اوس لاړ شه، دغه قوم هغه ځای ته بوځه چې ما درته وویل او زما فرښته به ستا لارښوونه کوي. نو کله چې د هغوی د سزا وخت راشي، زه به هغوی ته د خپلې ګناه سزا ورکړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus32_verse_34.mp3', '', 1761754199, 1761754199),
(43213, 'Exodus 32:35', 'Exodus', 32, 35, 'بیا څښتن په قوم باندې بلا نازله کړه، ځکه چې هغوی په هارون باندې د سرو زرو خوسی جوړ کړی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus32_verse_35.mp3', '', 1761754199, 1761754199),
(43214, 'Psalms 144:1', 'Psalms', 144, 1, 'ثنا او صفت دې وي څښتن ته چې دی ساتونکی زما چې راکوي راته روزنه د جګړې دپاره او تیاروي مې جنګ ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms144_verse_1.mp3', '', 1761754199, 1761754199),
(43215, 'Psalms 144:2', 'Psalms', 144, 2, 'هغه زما مینه ناک خدای دی او قوي کلا ده زما دی پناه ځای او ژغورونکی زما هغه دی سپر زما چې په کې اخلم پناه او خلک راولي زما د فرمان لاندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms144_verse_2.mp3', '', 1761754199, 1761754199),
(43216, 'Psalms 144:3', 'Psalms', 144, 3, 'ای څښتنه، انسان څه دی چې پرې پام کوې فاني انسان چې ته یې خیال ساتې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms144_verse_3.mp3', '', 1761754199, 1761754199),
(43217, 'Psalms 144:4', 'Psalms', 144, 4, 'هغه دی لکه د ساه په شان عمر یې تېریږي لکه سیوري په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms144_verse_4.mp3', '', 1761754199, 1761754199),
(43218, 'Psalms 144:5', 'Psalms', 144, 5, 'دروازې خلاصې کړه د خپلو اسمانونو ای څښتنه او شه راښکته لاندې غرونو ته لاس وروړه چې ترې لوګی پورته شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms144_verse_5.mp3', '', 1761754199, 1761754199),
(43219, 'Psalms 144:6', 'Psalms', 144, 6, 'ته راولېږه برېښنا او تندر او خواره واره کړه دښمنان دې خپل غشي ګوزار کړه او وارخطا کړه هغوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms144_verse_6.mp3', '', 1761754199, 1761754199),
(43220, 'Psalms 144:7', 'Psalms', 144, 7, 'لاس دې را‌اوږد کړه له اسمانه ژورو اوبو نه مې راوباسه او راکړه خلاصون ما کړه خلاص د پردو خلکو د لاسونو څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms144_verse_7.mp3', '', 1761754199, 1761754199),
(43221, 'Psalms 144:8', 'Psalms', 144, 8, 'چې هغوی هېڅکله رښتیا نه وایي او خوري قسم په دروغو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms144_verse_8.mp3', '', 1761754199, 1761754199),
(43222, 'Psalms 144:9', 'Psalms', 144, 9, 'ای خدایه، نوې سندره به زه وایم تاته زه تاته وایم به سندرې د چنګ په غږولو سره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms144_verse_9.mp3', '', 1761754199, 1761754199),
(43223, 'Psalms 144:10', 'Psalms', 144, 10, 'ته پاچاهانو ته بری ورکوې او ته خلاصون ورکوې خپل خدمتګار داود ته د وژونکې تورې څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms144_verse_10.mp3', '', 1761754199, 1761754199),
(43224, 'Psalms 144:11', 'Psalms', 144, 11, 'ماته خلاصون راکړه ما کړه خلاص د پردو خلکو د لاسونو څخه چې هغوی هېڅکله رښتیا نه وایي او خوري قسم په دروغو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms144_verse_11.mp3', '', 1761754199, 1761754199),
(43225, 'Psalms 144:12', 'Psalms', 144, 12, 'زمونږ زامن دې په ځوانۍ کې شي قوي لکه د بوټو په شان زمونږ لورګانې دې وي د ښایسته ستنو په شان چې پرې سینګار وي د ماڼۍ کنجونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms144_verse_12.mp3', '', 1761754199, 1761754199),
(43226, 'Psalms 144:13', 'Psalms', 144, 13, 'ګودامونه دې وي ډک زمونږه د هر ډول غلو دانو په څړځایونو کې دې مېږې زمونږ راوړي بچي په زرونو او لس ګونو زرو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms144_verse_13.mp3', '', 1761754199, 1761754199),
(43227, 'Psalms 144:14', 'Psalms', 144, 14, 'زمونږ غواګانې دې بچي راوړي پرېمانه او درز دې نه وي زمونږ د ښار په دېوالونو کې او څوک دې یو نه وړل شي په اسارت باندې د غم ژړا دې نه وي زمونږ کوڅو کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms144_verse_14.mp3', '', 1761754199, 1761754199),
(43228, 'Psalms 144:15', 'Psalms', 144, 15, 'بختور دي هغه خلک چې پرې وي برکتونه داسې بختور دي هغه خلک چې څښتن یې خدای دی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms144_verse_15.mp3', '', 1761754199, 1761754199),
(43229, 'Numbers 10:1', 'Numbers', 10, 1, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers10_verse_1.mp3', '', 1761754199, 1761754199),
(43230, 'Numbers 10:2', 'Numbers', 10, 2, '«د ټکول شویو سپینو زرو څخه دوه سرني جوړ کړه. د هغو څخه به د خلکو د راټولولو او د کمپ د لېرې کولو دپاره کار اخیستل کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers10_verse_2.mp3', '', 1761754199, 1761754199),
(43231, 'Numbers 10:3', 'Numbers', 10, 3, 'کله چې دواړه سرني ووهل شي، ټول قوم دې د سپېڅلې خېمې د دروازې په خوله کې تاته راټول شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers10_verse_3.mp3', '', 1761754199, 1761754199),
(43232, 'Numbers 10:4', 'Numbers', 10, 4, 'که چېرې یو سرنی ووهل شي، یوازې د قبیلو مشران دې درته راټول شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers10_verse_4.mp3', '', 1761754199, 1761754199),
(43233, 'Numbers 10:5', 'Numbers', 10, 5, 'کله چې سرني ووهل شي، کومې قبیلې چې په ختیځ کې کمپ لري، هغوی به حرکت کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers10_verse_5.mp3', '', 1761754199, 1761754199),
(43234, 'Numbers 10:6', 'Numbers', 10, 6, 'کله چې هغه د دوهم ځل دپاره ووهل شي، کومې قبیلې چې په جنوب کې دي، هغوی به حرکت کوي. نو هغه دې ووهل شي، د دې دپاره چې کمپ ته حرکت ورکړای شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers10_verse_6.mp3', '', 1761754199, 1761754199),
(43235, 'Numbers 10:7', 'Numbers', 10, 7, 'خو د دې دپاره چې ټول خلک راټول شي، هغه دې په دوامداره توګه ووهل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers10_verse_7.mp3', '', 1761754199, 1761754199),
(43236, 'Numbers 10:8', 'Numbers', 10, 8, 'د هارون زامن چې کاهنان دي، سرني دې ووهي. دا قانون باید د تل دپاره ستاسو او ستاسو د راتلونکو نسلونو له خوا مراعت شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers10_verse_8.mp3', '', 1761754199, 1761754199),
(43237, 'Numbers 10:9', 'Numbers', 10, 9, 'کله چې تاسو په خپله خاوره کې جنګېږئ او د هغو دښمنانو په وړاندې چې په تاسو باندې یې حمله کړې ده د خپلو ځانونو څخه دفاع کوئ، نو په دې سرنیو باندې د جګړې دپاره اشاره ورکړئ. زه یعنې ستاسو څښتن خدای به تاسو سره مرسته وکړم او د خپلو دښمنانو څخه به مو وژغورم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers10_verse_9.mp3', '', 1761754199, 1761754199),
(43238, 'Numbers 10:10', 'Numbers', 10, 10, 'همدارنګه د خپلې خوشحالۍ په وختونو کې، ستاسو د نوې میاشتې په اخترونو او په نورو اخترونو کې کله چې تاسو سوځېدونکې او د سلامتۍ نذرانې وړاندې کوئ، باید سرني ووهئ. بیا به زه درسره مرسته وکړم. زه ستاسو څښتن خدای یم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers10_verse_10.mp3', '', 1761754199, 1761754199),
(43239, 'Numbers 10:11', 'Numbers', 10, 11, 'د دوهم کال د دوهمې میاشتې په شلمه ورځ یعنې وروسته له دې چې اسراییلیان د مصر څخه راووتل، هغه ورېځ چې په سپېڅلې خېمې باندې ولاړه وه، پورته شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers10_verse_11.mp3', '', 1761754199, 1761754199),
(43240, 'Numbers 10:12', 'Numbers', 10, 12, 'نو اسراییلیان د سینا د دښتې څخه روان شول او د یو ځای څخه یې بل ځای ته سفر کاوه، ترڅو چې ورېځ د فاران په دښته کې ودرېدله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers10_verse_12.mp3', '', 1761754199, 1761754199),
(43241, 'Numbers 10:13', 'Numbers', 10, 13, 'دا اول ځل ؤ چې څښتن موسی ته وویل چې د اسراییلو قوم ته امر وکړي چې حرکت وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers10_verse_13.mp3', '', 1761754199, 1761754199),
(43242, 'Numbers 10:14', 'Numbers', 10, 14, 'هغه کس چې د یهودا قبیلې یې مشري کوله، د خپل بیرغ لاندې د عمیناداب د زوی نحشون په مشرۍ اول حرکت وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers10_verse_14.mp3', '', 1761754199, 1761754199),
(43243, 'Numbers 10:15', 'Numbers', 10, 15, 'نتناییل د صوغر زوی د یساکار د قبیلې مشر ؤ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers10_verse_15.mp3', '', 1761754199, 1761754199),
(43244, 'Numbers 10:16', 'Numbers', 10, 16, 'او الیاب د حیلون زوی د زبولون د قبیلې مشر ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers10_verse_16.mp3', '', 1761754199, 1761754199),
(43245, 'Numbers 10:17', 'Numbers', 10, 17, 'بیا سپېڅلې خېمه راټوله کړای شوه او جرشونیانو او مراریانو چې هغه یې وړله، حرکت وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers10_verse_17.mp3', '', 1761754199, 1761754199),
(43246, 'Numbers 10:18', 'Numbers', 10, 18, 'له هغې وروسته د روبین قبیلې تر خپل بیرغ لاندې چې د شدییور زوی الیصور د هغه مشري کوله، حرکت وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers10_verse_18.mp3', '', 1761754199, 1761754199),
(43247, 'Numbers 10:19', 'Numbers', 10, 19, 'شلومي ییل د صوریشدای زوی د شمعون د قبیلې مشر ؤ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers10_verse_19.mp3', '', 1761754199, 1761754199),
(43248, 'Numbers 10:20', 'Numbers', 10, 20, 'او الیاساف د دعویل زوی د جاد د قبیلې مشر ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers10_verse_20.mp3', '', 1761754199, 1761754199),
(43249, 'Numbers 10:21', 'Numbers', 10, 21, 'د هغوی پسې قهاتیانو چې د لاویانو د طایفو څخه وو، حرکت وکړ او سپېڅلي شیان یې وړل. کله چې هغوی بل کمپ ته ورسېدل، خېمه ودرول شوې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers10_verse_21.mp3', '', 1761754199, 1761754199),
(43250, 'Numbers 10:22', 'Numbers', 10, 22, 'ورپسې د افرایم قبیلې تر خپل بیرغ لاندې، د عمیهود د زوی الیشمع په مشرۍ حرکت وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers10_verse_22.mp3', '', 1761754199, 1761754199),
(43251, 'Numbers 10:23', 'Numbers', 10, 23, 'جملي ییل د فدهصور زوی د منسي د قبیلې مشر ؤ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers10_verse_23.mp3', '', 1761754199, 1761754199),
(43252, 'Numbers 10:24', 'Numbers', 10, 24, 'او ابیدان د جدعوني زوی د بنیامین د قبیلې مشر ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers10_verse_24.mp3', '', 1761754199, 1761754199),
(43253, 'Numbers 10:25', 'Numbers', 10, 25, 'په اخر کې هغه کس چې د دان قبیلې یې مشري کوله او د شا له خوا حملې په وړاندې به یې د اسراییلیانو ساتنه کوله د خپل بیرغ لاندې د عمیشدای د زوی اخیعزر په مشرۍ حرکت وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers10_verse_25.mp3', '', 1761754199, 1761754199),
(43254, 'Numbers 10:26', 'Numbers', 10, 26, 'فجعییل د عکران زوی د اشیر د قبیلې مشر ؤ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers10_verse_26.mp3', '', 1761754199, 1761754199),
(43255, 'Numbers 10:27', 'Numbers', 10, 27, 'او اخیرع د عینان زوی د نفتالي د قبیلې مشر ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers10_verse_27.mp3', '', 1761754199, 1761754199),
(43256, 'Numbers 10:28', 'Numbers', 10, 28, 'په دې ډول هرځل چې هغوی خپل کمپ د یو ځای څخه بل ځای ته وړلو، نو د اسراییلو خلکو به حرکت کاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers10_verse_28.mp3', '', 1761754199, 1761754199),
(43257, 'Numbers 10:29', 'Numbers', 10, 29, 'موسی خپل د ښځې ورور حوباب ته چې د مدیاني یترون زوی ؤ، وویل: «مونږ هغه ځای ته روان یو چې څښتن ویلي دي چې هغه مونږ ته راکوي. هغه زمونږ سره دا وعده کړې ده چې اسراییلیان به نېکمرغه کړي. نو زمونږ سره راشه او مونږ به دا نېکمرغي تاسو سره شریکه کړو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers10_verse_29.mp3', '', 1761754199, 1761754199),
(43258, 'Numbers 10:30', 'Numbers', 10, 30, 'حوباب په ځواب کې وویل: «نه، زه نه ځم، زه بېرته خپل وطن او خپلو خلکو ته ځم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers10_verse_30.mp3', '', 1761754199, 1761754199),
(43259, 'Numbers 10:31', 'Numbers', 10, 31, 'موسی ورته وویل: «مهرباني وکړه زمونږ سره لاړ شه! ته به زمونږ لارښوونکی اوسې، ځکه چې په دښته کې د خېمو د ودرولو ځایونه پېژنې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers10_verse_31.mp3', '', 1761754199, 1761754199),
(43260, 'Numbers 10:32', 'Numbers', 10, 32, 'که چېرې ته زمونږ سره لاړ شې، مونږ به درته د هغو ښو شیانو برخه درکړو چې څښتن یې مونږ ته راکوي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers10_verse_32.mp3', '', 1761754199, 1761754199),
(43261, 'Numbers 10:33', 'Numbers', 10, 33, 'نو د اسراییلو قوم د سینا یعنې د سپېڅلي غره څخه روان شو او هغوی درې ورځې سفر وکړ. د څښتن د لوظ صندوق تل د هغوی په مخکې روان ؤ، ترڅو د هغوی دپاره ځای پیدا کړي چې خېمې په کې ودروي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers10_verse_33.mp3', '', 1761754199, 1761754199),
(43262, 'Numbers 10:34', 'Numbers', 10, 34, 'څنګه به چې هغوی د هر کمپ څخه حرکت کاوه، د څښتن ورېځ به د ورځې له خوا د هغوی په سر باندې ولاړه وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers10_verse_34.mp3', '', 1761754199, 1761754199),
(43263, 'Numbers 10:35', 'Numbers', 10, 35, 'هرکله به چې د لوظ صندوق روان شو، نو موسی به ویل: «ای څښتنه، خپل دښمنان دې خواره واره کړه او هغوی چې ستا څخه کرکه کوي په تېښته مجبور کړه!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers10_verse_35.mp3', '', 1761754199, 1761754199),
(43264, 'Numbers 10:36', 'Numbers', 10, 36, 'او چې کله به د لوظ صندوق ودرېده، موسی به داسې دعا کوله: «ای څښتنه، د اسراییلو د زرګونو، زرګونو خلکو سره نژدې اوسه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers10_verse_36.mp3', '', 1761754199, 1761754199),
(43265, 'Leviticus 24:1', 'Leviticus', 24, 1, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus24_verse_1.mp3', '', 1761754199, 1761754199),
(43266, 'Leviticus 24:2', 'Leviticus', 24, 2, '«اسراییلیانو ته امر وکړه چې د هغو څراغونو دپاره چې په سپېڅلې خېمه کې دي د زیتونو سوچه تېل راوړي، ترڅو هغه په دوامداره توګه بل وساتل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus24_verse_2.mp3', '', 1761754199, 1761754199),
(43267, 'Leviticus 24:3', 'Leviticus', 24, 3, 'هارون دې هر ماښام هغه بل کړي او هغه دې تر سهاره پورې د څښتن په حضور کې د پردې څخه دباندې د لوظ د صندوق په مخکې چې په ډېر سپېڅلي ځای کې دی، بل وساتي. دا حکم دې د تل دپاره مراعت شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus24_verse_3.mp3', '', 1761754199, 1761754199),
(43268, 'Leviticus 24:4', 'Leviticus', 24, 4, 'هارون باید په هغو څراغونو باندې پام وکړي چې د سوچه سرو زرو په څراغدان باندې دي او وګوري چې هغه په منظمه توګه د څښتن په حضور کې بل وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus24_verse_4.mp3', '', 1761754199, 1761754199),
(43269, 'Leviticus 24:5', 'Leviticus', 24, 5, 'څلورویشت کیلو ګرامه ښه اوړه واخله او دولس ډوډۍ ورڅخه پخې کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus24_verse_5.mp3', '', 1761754199, 1761754199),
(43270, 'Leviticus 24:6', 'Leviticus', 24, 6, 'دا ډوډۍ په دوه قطارونو کې چې په هر قطار کې شپږ ډوډۍ وي، په هغه مېز باندې کېږده چې په سوچه سرو زرو پوښل شوی دی او د څښتن په حضور کې دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus24_verse_6.mp3', '', 1761754199, 1761754199),
(43271, 'Leviticus 24:7', 'Leviticus', 24, 7, 'په هر قطار باندې لږه سوچه او قیمتي خوشبویي واچوه چې دا خوشبویي به څښتن خدای ته په اور باندې د تیارېدونکې نذرانې د یوې نښې په شان وي چې د ډوډۍ په ځای وړاندې کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus24_verse_7.mp3', '', 1761754199, 1761754199),
(43272, 'Leviticus 24:8', 'Leviticus', 24, 8, 'دا ډوډۍ دې په هر سبت کې د څښتن په حضور کې کېښودل شي. دا د تل دپاره د اسراییلو دنده ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus24_verse_8.mp3', '', 1761754199, 1761754199),
(43273, 'Leviticus 24:9', 'Leviticus', 24, 9, 'دا ډوډۍ د هارون او د هغه د اولادې ده. هغوی دې هغه په یو سپېڅلي ځای کې وخوري، ځکه چې دا د هغو نذرانو یوه ډېره سپېڅلې برخه ده چې څښتن ته په اور باندې تیاریږي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus24_verse_9.mp3', '', 1761754199, 1761754199),
(43274, 'Leviticus 24:12', 'Leviticus', 24, 12, 'هغه یې تر څارنې لاندې وساته او څښتن ته یې انتظار کاوه چې دوی ته ووایي چې د هغه سره څه وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus24_verse_12.mp3', '', 1761754199, 1761754199),
(43275, 'Leviticus 24:13', 'Leviticus', 24, 13, 'بیا څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus24_verse_13.mp3', '', 1761754199, 1761754199),
(43276, 'Leviticus 24:14', 'Leviticus', 24, 14, '«کفر ویونکی د کمپ څخه دباندې وباسه. هرچا چې د هغه ښکنځلې چې څښتن ته یې کړې دي اورېدلې وي، خپل لاسونه دې د هغه په سر باندې کېږدي او ټول قوم دې هغه سنګسار کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus24_verse_14.mp3', '', 1761754199, 1761754199),
(43277, 'Leviticus 24:15', 'Leviticus', 24, 15, 'اسراییلیانو ته ووایه: که چېرې څوک خدای ته ښکنځلې وکړي، نو هغه به د خپلو بدو سزا وویني.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus24_verse_15.mp3', '', 1761754199, 1761754199),
(43278, 'Leviticus 24:16', 'Leviticus', 24, 16, 'هرڅوک چې د څښتن په نوم کفر ووایي، باید ووژل شي. ټول قوم باید هغه سنګسار کړي. که هغه یو پردی کس وي یا اسراییلی وي، کله چې هغه د خدای په نوم کفر ووایي، باید ووژل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus24_verse_16.mp3', '', 1761754199, 1761754199),
(43279, 'Leviticus 24:17', 'Leviticus', 24, 17, 'هرڅوک چې قتل وکړي، باید ووژل شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus24_verse_17.mp3', '', 1761754199, 1761754199),
(43280, 'Leviticus 24:18', 'Leviticus', 24, 18, 'او هرڅوک چې د بل چا حیوان ووژني، باید تاوان یې ورکړي. قانون دا دی چې د ژوند په بدل کې ژوند واخیستل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus24_verse_18.mp3', '', 1761754199, 1761754199),
(43281, 'Leviticus 24:19', 'Leviticus', 24, 19, 'که چېرې یو څوک یو بل کس ټپي کړي، هرڅه چې هغه کړي وي، هماغه شان عمل به ورسره کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus24_verse_19.mp3', '', 1761754199, 1761754199),
(43282, 'Leviticus 24:20', 'Leviticus', 24, 20, 'که چېرې تاسو د چا یو هډوکی مات کړئ، ستاسو یو هډوکی به مات شي. که چېرې تاسو د چا یوه سترګه وباسئ، ستاسو یوه سترګه به وویستل شي. که چېرې تاسو د چا یو غاښ مات کړئ، ستاسو یو غاښ به مات شي. څنګه چې تاسو یو بل کس ټپي کړئ، تاسو سره به په بدل کې هماغه شان کار کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus24_verse_20.mp3', '', 1761754199, 1761754199),
(43283, 'Leviticus 24:21', 'Leviticus', 24, 21, 'هرڅوک چې یو حیوان ووژني تاوان به یې ورکوي، خو څوک چې یو انسان ووژني، هغه به ووژل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus24_verse_21.mp3', '', 1761754199, 1761754199),
(43284, 'Leviticus 24:22', 'Leviticus', 24, 22, 'دا قانون په تاسو ټولو باندې عملي کیږي، یعنې په اسراییلیانو او په هغو پردیو خلکو باندې چې ستاسو په منځ کې اوسیږي، ځکه چې زه ستاسو څښتن خدای یم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus24_verse_22.mp3', '', 1761754199, 1761754199),
(43285, 'Leviticus 24:23', 'Leviticus', 24, 23, 'کله چې موسی د اسراییلو قوم ته دا خبرې وکړې، هغوی دا سړی د کمپ څخه دباندې وویست او سنګسار یې کړ. په دې ډول د اسراییلو قوم هغه څه وکړل چې څښتن یې موسی ته امر کړی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus24_verse_23.mp3', '', 1761754199, 1761754199),
(43286, 'Hosea 3:1', 'Hosea', 3, 1, 'څښتن ماته وویل: «یوځل بیا لاړ شه او هغې ښځې ته خپله مینه وښایه چې د خپل عاشق سره زنا کوي. د هغې سره به داسې مینه کوې لکه څنګه چې زه یې د اسراییلو د خلکو سره کوم، که څه هم هغوی نورو خدایانو ته اووښتي دي او بتانو ته د ممیزو د کلچو نذرانې وړاندې کول خوښوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea3_verse_1.mp3', '', 1761754199, 1761754199),
(43287, 'Hosea 3:2', 'Hosea', 3, 2, 'نو ما هغه ښځه د سپینو زرو په پنځلسو سکو او یوسلو پنځوسو کیلو‌ګرامه اوربشو باندې واخیستله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea3_verse_2.mp3', '', 1761754199, 1761754199),
(43288, 'Hosea 3:3', 'Hosea', 3, 3, 'ما هغې ته وویل چې ته به د ډېر وخت دپاره زما په کور کې اوسېږې او فاحشه‌توب به نه کوي او د هېچا سره به جنسي اړیکې نه ساتې، حتی زما سره هم نه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea3_verse_3.mp3', '', 1761754199, 1761754199),
(43289, 'Hosea 3:4', 'Hosea', 3, 4, 'په همدې ډول به د اسراییلو خلک د زیات وخت دپاره بې له پاچاهانو او مشرانو، قربانیو او د تیږو ستنو، د کاهنانو او کورني بتانو چې د فال کتلو دپاره ورڅخه کار اخیستل کیږي، ژوند تېروي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea3_verse_4.mp3', '', 1761754199, 1761754199),
(43290, 'Hosea 3:5', 'Hosea', 3, 5, 'خو هغه وخت به راشي چې د اسراییلو خلک به یوځل بیا خپل څښتن خدای او د خپل پاچا داود اولادې ته راوګرځي. په اخره زمانه کې به هغوی له وېرې د څښتن حضور ته راځي او د هغه ښه نعمتونه به لاسته راوړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea3_verse_5.mp3', '', 1761754199, 1761754199),
(43291, 'Leviticus 13:1', 'Leviticus', 13, 1, 'څښتن موسی او هارون ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_1.mp3', '', 1761754199, 1761754199),
(43292, 'Leviticus 13:2', 'Leviticus', 13, 2, '«کله چې د چا په پوستکي باندې زخم، دانه یا داغ وي چې کېدای شي هغه د پوستکي په یوې ساري ناروغۍ باندې بدله شي، هغه باید هارون کاهن یا د هغه یو زوی ته چې کاهن وي راوستل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_2.mp3', '', 1761754199, 1761754199),
(43293, 'Leviticus 13:3', 'Leviticus', 13, 3, 'کاهن دې د هغه زخم معاینه کړي او که چېرې په هغه کې ویښتان سپین شوي وو او زخم د پوستکي څخه ژور ښکاره کېده، نو دا د پوستکي ساري ناروغي ده. نو کاهن به هغه کس ناپاک اعلان کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_3.mp3', '', 1761754199, 1761754199),
(43294, 'Leviticus 13:4', 'Leviticus', 13, 4, 'که چېرې د هغه د پوستکي زخم سپین ؤ، خو د پوستکي څخه ژور نه ښکاره کېده او ویښتان په کې سپین شوي نه وو، کاهن دې هغه ناروغه کس د اوو ورځو دپاره د نورو څخه بېل وساتي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_4.mp3', '', 1761754199, 1761754199),
(43295, 'Leviticus 13:5', 'Leviticus', 13, 5, 'کاهن به په اوومه ورځ هغه بیا معاینه کړي او که چېرې د هغه په نظر کې زخم هماغه شان ښکاره کېده او خپور شوی نه ؤ، کاهن به هغه د نورو اوو ورځو دپاره بېل وساتي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_5.mp3', '', 1761754199, 1761754199),
(43296, 'Leviticus 13:6', 'Leviticus', 13, 6, 'په اوومه ورځ دې کاهن هغه د دوهم ځل دپاره معاینه کړي. که چېرې زخم مړاوی شوی ؤ او په پوستکي کې نه ؤ خپور شوی، کاهن به هغه پاک اعلان کړي، دا یوازې یوه ګرمکه ده. هغه کس باید خپل کالي ووینځي او هغه به پاک شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_6.mp3', '', 1761754199, 1761754199),
(43297, 'Leviticus 13:7', 'Leviticus', 13, 7, 'خو که چېرې کاهن هغه کس معاینه کړی وي او هغه یې پاک اعلان کړی وي او له هغې څخه وروسته ګرمکه د هغه په بدن باندې خپره شي، هغه باید خپل ځان بیا کاهن ته ورښکاره کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_7.mp3', '', 1761754199, 1761754199),
(43298, 'Leviticus 13:8', 'Leviticus', 13, 8, 'کاهن دې هغه معاینه کړي، که چېرې هغه ګرمکه په بدن باندې خپره شوې وه، کاهن به هغه ناپاک اعلان کړي، دا یوه ساري ناروغي ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_8.mp3', '', 1761754199, 1761754199),
(43299, 'Leviticus 13:9', 'Leviticus', 13, 9, 'کله چې یو کس د پوستکي ساري ناروغي ولري، هغه باید کاهن ته راوستل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_9.mp3', '', 1761754199, 1761754199),
(43300, 'Leviticus 13:10', 'Leviticus', 13, 10, 'کاهن دې هغه معاینه کړي، که چېرې په پوستکي کې یو سپین زخم وي چې ویښتان یې سپین کړي وي او که چېرې په زخم کې خامه غوښه وي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_10.mp3', '', 1761754199, 1761754199),
(43301, 'Leviticus 13:11', 'Leviticus', 13, 11, 'نو دا د پوستکي یوه دوامداره ناروغي ده او کاهن به هغه ناپاک اعلان کړي. کاهن دې هغه د معاینې دپاره بېل ونه ساتي، ځکه چې هغه په ښکاره ناپاک دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_11.mp3', '', 1761754199, 1761754199),
(43302, 'Leviticus 13:14', 'Leviticus', 13, 14, 'خو هرکله چې په هغه باندې خامه غوښه راښکاره شي، هغه به ناپاک شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_14.mp3', '', 1761754199, 1761754199),
(43303, 'Leviticus 13:15', 'Leviticus', 13, 15, 'کله چې کاهن دا خامه غوښه وویني، هغه کس به ناپاک اعلان کړي. خامه غوښه ناپاکه ده، هغه کس په ساري ناروغۍ اخته دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_15.mp3', '', 1761754199, 1761754199),
(43304, 'Leviticus 13:16', 'Leviticus', 13, 16, 'خو کله چې دا خامه غوښه روغه شي او بیا سپینه شي، هغه کس باید کاهن ته ورشي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_16.mp3', '', 1761754199, 1761754199),
(43305, 'Leviticus 13:17', 'Leviticus', 13, 17, 'کاهن دې هغه معاینه کړي، که چېرې د زخم څخه یوازې سپین داغونه پاتې وي کاهن به هغه ناروغه کس پاک اعلان کړي، بیا به هغه پاک شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_17.mp3', '', 1761754199, 1761754199),
(43306, 'Leviticus 13:18', 'Leviticus', 13, 18, 'کله چې د یو چا په پوستکي باندې یوه دانه وي او روغه شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_18.mp3', '', 1761754199, 1761754199),
(43307, 'Leviticus 13:19', 'Leviticus', 13, 19, 'او په هغه ځای باندې چې دانه وه، یو زخم یا سوربخن سپین داغ راښکاره شي، هغه باید خپل ځان کاهن ته ورښکاره کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_19.mp3', '', 1761754199, 1761754199),
(43308, 'Leviticus 13:20', 'Leviticus', 13, 20, 'کاهن دې هغه معاینه کړي، که چېرې هغه د پوستکي څخه ژور وي او ویښتان په کې سپین شوي وي، کاهن به هغه ناپاک اعلان کړي. دا د پوستکي یوه ساري ناروغي ده چې د دانې په ځای منځ ته راغلې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_20.mp3', '', 1761754199, 1761754199),
(43309, 'Leviticus 13:21', 'Leviticus', 13, 21, 'خو که چېرې کاهن هغه معاینه کړي او سپین ویښتان په کې نه وي او د پوستکي څخه ژور نه وي او مړاوی شوی وي، بیا دې کاهن هغه کس د اوو ورځو دپاره بېل وساتي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_21.mp3', '', 1761754199, 1761754199),
(43310, 'Leviticus 13:22', 'Leviticus', 13, 22, 'که چېرې هغه زخم په پوستکي کې خپریږي، کاهن به هغه کس ناپاک اعلان کړي، دا ساري ناروغي ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus13_verse_22.mp3', '', 1761754199, 1761754199);